/**
 * Copy Installer to Project Root
 * 
 * Automatically copies the final Windows NSIS installer executable generated by
 * electron-builder from the `release` directory directly into the main project root folder
 * with the standard human-readable name:
 * "MS Institute Management System Setup.exe"
 */

import * as fs from 'fs';
import * as path from 'path';

const rootDir = process.cwd();
const releaseDir = path.join(rootDir, 'release');
const targetInstallerName = 'MS Institute Management System Setup.exe';

const targetRootPath = path.join(rootDir, targetInstallerName);

console.log('[Post-Build] Checking release artifacts in:', releaseDir);

if (!fs.existsSync(releaseDir)) {
  console.error(`[Post-Build Error] Release directory not found: ${releaseDir}`);
  process.exit(1);
}

// 1. Check for exact name match first
const directPath = path.join(releaseDir, targetInstallerName);
let sourcePath = null;

if (fs.existsSync(directPath)) {
  sourcePath = directPath;
} else {
  // 2. Search for any generated setup executable in release directory
  const files = fs.readdirSync(releaseDir);
  const exeCandidates = files.filter(
    (f) => f.toLowerCase().endsWith('.exe') && !f.toLowerCase().includes('uninstaller')
  );

  if (exeCandidates.length > 0) {
    // Sort by modified time descending to pick the freshest
    exeCandidates.sort((a, b) => {
      const statA = fs.statSync(path.join(releaseDir, a));
      const statB = fs.statSync(path.join(releaseDir, b));
      return statB.mtimeMs - statA.mtimeMs;
    });
    sourcePath = path.join(releaseDir, exeCandidates[0]);
  }
}

if (!sourcePath || !fs.existsSync(sourcePath)) {
  console.error(`[Post-Build Error] Could not find generated installer in ${releaseDir}`);
  process.exit(1);
}

console.log(`[Post-Build] Copying installer:`);
console.log(`  Source: ${sourcePath}`);
console.log(`  Target: ${targetRootPath}`);

try {
  fs.copyFileSync(sourcePath, targetRootPath);
  const stats = fs.statSync(targetRootPath);
  const sizeMB = (stats.size / (1024 * 1024)).toFixed(2);

  console.log('\n===============================================================');
  console.log('✓ FINAL PRODUCTION WINDOWS INSTALLER READY IN PROJECT ROOT:');
  console.log(`  File: ${targetInstallerName}`);
  console.log(`  Path: ${targetRootPath}`);
  console.log(`  Size: ${sizeMB} MB (${stats.size} bytes)`);
  console.log('===============================================================\n');
} catch (err) {
  console.error('[Post-Build Error] Failed to copy installer to project root:', err);
  process.exit(1);
}
